const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const {today,addDays,remaining,status,validRecord,paymentTotals,validPayment,migratePayment,validFee,validPartner,validFinance,accountLabels,channelLabels,validRouting,routePayment}=Educa;
const KEY='educa-workspace-v1';
const money=v=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const parseBRL=v=>{const text=String(v??'').trim();if(!text)return 0;if(!/[R$.,]/.test(text))return Number(text)||0;const normalized=text.replace(/[^\d,.-]/g,'').replace(/\./g,'').replace(',','.');return Number(normalized)||0};
const formatBRLInput=v=>money(parseBRL(v));
function maskMoneyInput(input){const digits=input.value.replace(/\D/g,'');input.value=money((Number(digits)||0)/100)}
function maskPhoneInput(input){const digits=input.value.replace(/\D/g,'').slice(0,13);const local=digits.startsWith('55')&&digits.length>11?digits.slice(2):digits;input.value=local.length<=10?local.replace(/^(\d{0,2})(\d{0,4})(\d{0,4}).*/,(_,a,b,c)=>[a&&`(${a}`,a&&a.length===2?') ':'',b,c&&`-${c}`].join('')):local.replace(/^(\d{0,2})(\d{0,5})(\d{0,4}).*/,(_,a,b,c)=>[a&&`(${a}`,a&&a.length===2?') ':'',b,c&&`-${c}`].join(''))}
const date=v=>v?v.split('-').reverse().join('/'):'—';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
