let state;try{const saved=localStorage.getItem(KEY);state=saved?JSON.parse(saved):{demo:true,records:demo()};if(!Array.isArray(state.records)||!state.records.every(r=>validRecord(r)&&validFee(r)&&validPartner(r)&&validRouting(r)&&Educa.validSchedule(r)))throw Error();if(!validFinance(state))throw Error();state.records=state.records.map(migratePayment);state.expenses=(state.expenses??expenseExamples()).map(r=>({...r,expenseType:r.expenseType??'fixed',dueDate:r.dueDate??'',paidDate:r.paidDate??'',interest:r.interest??0}));state.adSpends=state.adSpends??[];state.taxRates=state.taxRates??{};}catch{state={demo:false,records:[],expenses:[],adSpends:[],taxRates:{}};alert('Não foi possível ler os dados salvos. Restaure um backup, se disponível.');}
