let financeMonth=today().slice(0,7);
function expenseExamples(){return [{id:crypto.randomUUID(),recurringKey:'marketing-template',name:'Marketing — gestão de anúncios',recipient:'',category:'marketing',expenseType:'fixed',month:today().slice(0,7),dueDate:'',paidDate:'',interest:0,amount:0,example:true},{id:crypto.randomUUID(),recurringKey:'erico-template',name:'Pacote de cursos — Érico',recipient:'Érico',category:'courses',expenseType:'fixed',month:today().slice(0,7),dueDate:'',paidDate:'',interest:0,amount:7000,example:true}];}
